import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);

        // Deploy a reverter that the fuzzed actor will use as its address
        Reverter reverter = new Reverter();
        address adversary = address(reverter);
        vm.assume(actor != adversary);

        // Fund and deposit from adversary so it has credit
        vm.deal(adversary, depositAmount);
        vm.prank(adversary);
        c.deposit{value: depositAmount}();

        // Record state before the adversary's withdrawAll
        uint256 contractBalanceBefore = address(c).balance;
        uint256 adversaryCreditBefore = c.credit(adversary);

        // Have the adversary call withdrawAll (the reverter's fallback reverts)
        vm.prank(adversary);
        try c.withdrawAll() { /* the call may or may not revert */ } catch { }

        // After the attempt, the contract's balance must not be less than
        // the sum of all remaining credits.
        // The adversary's credit is either 0 (if withdrawAll completed) or unchanged.
        // In the reference, a failed call reverts entirely, so credit unchanged and balance unchanged.
        // In the bug, balance can decrease while credit is zeroed, violating this invariant.
        assertTrue(
            address(c).balance >= c.credit(adversary),
            "invariant: contract balance >= sum of credits (here >= adversary credit)"
        );
    }
}

