pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address other) public {
        vm.assume(actor != address(0) && other != address(0) && actor != other);
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(actor != address(c) && other != address(c));

        // Deploy a re-entrant attacker that calls withdrawAll on receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        // actor will act through attacker, other is a regular depositor

        // Setup: credit for attacker's address and for other
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        vm.deal(other, amount);
        vm.prank(other);
        c.deposit{value: amount}();

        uint256 balBefore = address(c).balance;
        uint256 totalCreditBefore = getTotalCredit(address(attacker), other);

        // attacker triggers withdrawAll which will re-enter
        vm.prank(address(attacker));
        attacker.initiateWithdraw(amount);

        uint256 balAfter = address(c).balance;
        uint256 totalCreditAfter = getTotalCredit(address(attacker), other);

        // General invariant: after any sequence of calls, contract balance equals sum of all remaining credits
        assertEq(balAfter, totalCreditAfter);
    }

    function getTotalCredit(address addr1, address addr2) internal view returns (uint256) {
        return c.credit(addr1) + c.credit(addr2);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private reentering;

    constructor(C _target) {
        target = _target;
    }

    function initiateWithdraw(uint256 amount) external {
        reentering = true;
        target.withdrawAll();
        reentering = false;
    }

    receive() external payable {
        if (reentering) {
            // re-enter withdrawAll, which should revert in correct contract due to lock modifier
            // but if it doesn't revert, it will execute with credit already zeroed in buggy version
            try target.withdrawAll() {} catch {}
        }
    }
}

