pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address attacker;

    function setUp() public {
        c = new C();
        attacker = address(new ReentrantAttacker(address(c)));
    }

    function testFuzz_property(uint256 depositAmount, uint256 attackerAmount) public {
        // Keep amounts within reasonable bounds
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        attackerAmount = bound(attackerAmount, 1 ether, 100 ether);

        // Attacker deposits some funds
        vm.deal(attacker, attackerAmount);
        vm.prank(attacker);
        c.deposit{value: attackerAmount}();

        // Record attacker's initial credit
        uint256 attackerInitCredit = c.credit(attacker);

        // Make the attacker initiate withdrawAll; the constructed attacker calls back into c.withdrawAll() once
        vm.prank(attacker);
        ReentrantAttacker(attacker).attack();

        // After the entire sequence, the invariant is:
        // If attackerInitCredit == 0 (because deposit reverted due to overflow/zero amount? but bound avoids that),
        // then the invariant still holds regardless. The invariant is about credit sums.
        // The credit of the attacker after the call must be zero (all withdrawn),
        // and the ether balance of c must equal the sum of credits of all other depositors.
        // Here there are only two depositors: attacker and possibly some other address.
        // Since nobody else deposited, total credits = c.credit(attacker) + c.credit(address(0)) + ... = c.credit(attacker) (others 0).
        // Ether balance of c after call should equal total credits.
        uint256 totalCredits = c.credit(attacker) + c.credit(address(this)) + c.credit(address(0));
        assertEq(address(c).balance, totalCredits, "Invariant broken: ether balance != sum of credits");
    }
}

